window.products.push({"id":75712,"name":"Supplying Demand WH02X24399 4455158 Clothes Washer Lid Lock Striker Replacement","category":"homeandappliances","retail price":15.69,"sale price":null,"image":"https://m.media-amazon.com/images/I/71Cz8y1xJmL._AC_SL1500_.jpg","description":"Alternate part numbers include AP5999576 and PS11729471. Screws sold separately. WH02X24296 is the typical screw used on most compatible models. You should be able to reuse the original mounting screws. If your washer will not start, the lid or door won’t open/close properly, or the washer will not agitate you may need to replace your striker. It is important to disconnect your washing machine from the power and water supply before servicing. Supplying Demand replacement parts are compatible with Major Brands, but you should always verify fitment with your specific model. We have included a video in the product gallery to help you find your model number and information in the description below. SD products come in Supplying Demand packaging.","images":["https://m.media-amazon.com/images/I/71Cz8y1xJmL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Supplying Demand","source_asin":"B07V5K5WSP","category_path":"Home & Appliances"},"sku":"BM-75712","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07V5K5WSP","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B07V5K5WSP","price_pending":true,"merchant_ready":false});
